const menuButton=document.querySelector('.menu-toggle');const nav=document.querySelector('.main-nav');if(menuButton&&nav){menuButton.addEventListener('click',()=>{const open=menuButton.getAttribute('aria-expanded')!=='true';menuButton.setAttribute('aria-expanded',String(open));nav.classList.toggle('is-open',open)});nav.addEventListener('click',e=>{if(e.target.closest('a')){menuButton.setAttribute('aria-expanded','false');nav.classList.remove('is-open')}})}document.documentElement.dataset.skin='storybook';const map=document.querySelector('.route-map');if(map){const steps=[...map.querySelectorAll('.route-stop')];const mascot=map.querySelector('.route-mascot');const title=document.querySelector('#route-title');const detail=document.querySelector('#route-copy');const status=document.querySelector('#route-status');function position(btn){const m=map.getBoundingClientRect(),r=btn.getBoundingClientRect();mascot.style.left=(r.left-m.left+r.width/2)+'px';mascot.style.top=(r.top-m.top+25)+'px'}steps.forEach((btn,i)=>btn.addEventListener('click',()=>{steps.forEach(x=>x.removeAttribute('aria-current'));btn.setAttribute('aria-current','step');title.textContent=btn.dataset.title;detail.textContent=btn.dataset.detail;status.textContent='Durak '+String(i+1).padStart(2,'0')+' / 08';position(btn)}));window.addEventListener('resize',()=>{const current=steps.find(x=>x.hasAttribute('aria-current'))||steps[1];if(current)position(current)});if(steps[1])position(steps[1])}document.querySelectorAll('[data-admin-tab]').forEach(button=>button.addEventListener('click',()=>{document.querySelectorAll('[data-admin-tab]').forEach(x=>x.setAttribute('aria-pressed','false'));button.setAttribute('aria-pressed','true');document.querySelectorAll('[data-admin-panel]').forEach(panel=>panel.hidden=panel.dataset.adminPanel!==button.dataset.adminTab)}));